26	/** Backups list for this server, through its OWN node — vmids collide across
27	 *  physical nodes, so the bare singleton would silently show another node's
28	 *  server's backups once a second node has real traffic. */
29	async function listBackupsForServer(server: { vmid: number | null; node: any }): Promise<ServerBackup[]> {
30	  if (!server.vmid) return [];
31	  if (!server.node) return (await listBackups(server.vmid)) as ServerBackup[];
32	  // Same divergence as provisioning/backupCreate: a non-primary node's
33	  // vzdump-archive storage is its own storageHdd, not literally "backup".
34	  const storage = server.node.isPrimary ? "backup" : (server.node.storageHdd ?? "backup");
35	  return (await listBackupsOn(pveForNode(server.node), server.vmid, storage)) as ServerBackup[];
36	}
