43	/** Reject if another job is already queued/running on this server. */
44	async function ensureIdle(serverId: string): Promise<{ error?: string }> {
45	  const pending = await db.job.count({
46	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
47	  });
48	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
49	  return {};
50	}
