101	// ---------- Self-service backup restore ----------
102	
103	export type ServerBackup = { volid: string; ctime?: number; size?: number };
104	
105	/**
106	 * List the vzdump backups on the `backup` storage that belong to this server's
107	 * VMID. Read-only Proxmox call, ownership-checked.
108	 */
109	export async function listServerBackups(
110	  serverId: string
111	): Promise<{ error?: string; backups?: ServerBackup[] }> {
112	  const { server } = await ownedServer(serverId);
113	  if (!server.vmid) return { backups: [] };
114	  try {
115	    const backups = await listBackupsForServer(server);
116	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
117	    return { backups };
118	  } catch {
119	    return { error: "Could not reach the hypervisor — try again in a moment." };
120	  }
121	}
122	
123	/**
124	 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
125	 * the server's current disk. The volid is validated against the server's own
126	 * backups so a customer can only restore their own VM's archives.
127	 */
128	export async function requestRestore(
129	  serverId: string,
130	  volid: string
131	): Promise<{ error?: string }> {
132	  const { user, server } = await ownedServer(serverId);
133	  if (!server.vmid) return { error: "Server has no VM yet." };
134	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
135	    return { error: "Server must be running or stopped to restore a backup." };
136	  }
137	
138	  // Validate the archive actually belongs to this server's VMID (prevents
139	  // restoring another customer's backup by guessing a volid).
140	  let owned: ServerBackup[];
141	  try {
142	    owned = await listBackupsForServer(server);
143	  } catch {
144	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
145	  }
146	  if (!owned.some((b) => b.volid === volid)) {
147	    return { error: "That backup was not found for this server." };
148	  }
149	
150	  // DATA SAFETY (critical): `qmrestore --force` over an existing VM calls PVE's
151	  // destroy_vm first ("avoid zombie disks when restoring over an existing VM"),
152	  // and destroy_vm frees EVERY volume the vmid owns, `unusedN` entries included.
153	  // Restoring a backup taken before a volume was attached therefore destroys that
154	  // volume's data silently, while `Volume.diskName` keeps pointing at the dead
155	  // volid and billing carries on.
156	  //
157	  // Reinstall already refuses for exactly this reason. Restore does the same thing
158	  // to the same vmid and had no guard at all — same rule, both layers.
159	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
160	  if (pinnedVolumes > 0) {
161	    return {
162	      error:
163	        `Restoring replaces this server's disks, which would also destroy the ` +
164	        `${pinnedVolumes} data volume${pinnedVolumes === 1 ? "" : "s"} assigned to it — ` +
165	        `including any you have detached. Move or delete them first, then restore.`,
166	    };
167	  }
168	
169	  const idle = await ensureIdle(serverId);
170	  if (idle.error) return idle;
171	
172	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
173	  await db.auditLog.create({
174	    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
175	  });
176	  revalidatePath(`/dashboard/servers/${serverId}`);
177	  return {};
178	}
