158	// ---------- Resize ----------
159	
160	export async function resizeServer(
161	  serverId: string,
162	  planId: string,
163	  useWallet: boolean = true,
164	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
165	  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
166	  // the customer's name), so it carries the same impersonation guard as every
167	  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
168	  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
169	  // This one was missed, which made "upgrade the plan" the one charge an admin
170	  // impersonating a customer could still put on that customer's balance.
171	  await assertNotImpersonating();
172	  const { user, server } = await ownedServer(serverId);
173	  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
174	  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
175	  // stopping a customer from spending LESS would be a gate with no one to
176	  // protect. See lib/email-verification.ts.
177	  const unverified = await emailVerificationError(user);
178	  if (unverified) return { error: unverified };
179	
180	  // Validate + price the upgrade (ownership already checked above). resizeQuote
181	  // recomputes the exact prorated charge over the remaining term.
182	  let quote;
183	  try {
184	    quote = await resizeQuote(serverId, planId);
185	  } catch (e) {
186	    if (e instanceof ResizeError) return { error: e.message };
187	    throw e;
188	  }
189	  const { newPlan, prorateCents } = quote;
190	
191	  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
192	  // the same split (lib/wallet-split.ts) so displayed === charged.
193	  const { cardCents } = walletSplit({
194	    dueCents: prorateCents,
195	    balanceCents: user.balanceCents,
196	    useWallet,
197	  });
198	
199	  // Card portion > 0 → charge ONLY the remainder on the card (not the full
200	  // proration). The confirm route credits the card amount to the wallet and then
201	  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
202	  // share and the card the rest — wallet never touched before the card clears.
203	  if (cardCents > 0) {
204	    const checkout = await createResizeCheckout(user, cardCents, {
205	      serverId,
206	      planId,
207	      planName: newPlan.name,
208	      prorateCents,
209	    });
210	    if (!checkout) {
211	      return {
212	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
213	      };
214	    }
215	    return { checkout };
216	  }
217	
218	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
219	  // servers) → apply instantly, debiting the full proration from the wallet.
220	  try {
221	    await applyResize({ serverId, planId, actorUserId: user.id });
222	  } catch (e) {
223	    if (e instanceof ResizeError) return { error: e.message };
224	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
225	    throw e;
226	  }
227	  revalidatePath(`/dashboard/servers/${serverId}`);
228	  return {};
229	}
