250	
251	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
252	const MAX_FORWARDS_PER_SERVER = 10;
253	
254	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
255	  const serverId = String(formData.get("serverId") ?? "");
256	  const { user, server } = await ownedServer(serverId);
257	  const parsed = z
258	    .object({
259	      guestPort: z.coerce.number().int().min(1).max(65535),
260	      protocol: z.enum(["tcp", "udp"]),
261	    })
262	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
263	  if (!parsed.success) return { error: "Invalid port." };
264	
265	  const count = await db.portForward.count({ where: { serverId } });
266	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
267	
268	  // Allocate the public port with the DB as the arbiter, not this read.
269	  //
270	  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
271	  // from a snapshot read and inserting it unguarded meant two requests that
272	  // overlapped — a double-click, or two customers adding a forward at the same
273	  // moment — both picked the same lowest free port and the loser's insert threw
274	  // a raw Prisma P2002. That exception escaped this action, so the customer got
275	  // a server-error page instead of a message, and (in production, where Next
276	  // redacts action errors) no clue what happened or that simply retrying works.
277	  //
278	  // Retry across the next few free candidates so an ordinary collision resolves
279	  // itself silently, and turn a genuine exhaustion into an honest, actionable
280	  // message rather than a crash.
281	  const used = new Set([
282	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
283	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
284	  ]);
285	  const candidates: number[] = [];
286	  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
287	    if (!used.has(p)) candidates.push(p);
288	  }
289	  if (candidates.length === 0) {
290	    return {
291	      error:
292	        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
293	        "Delete a forward you no longer need, or contact support to have the pool widened.",
294	    };
295	  }
296	
297	  let publicPort = 0;
298	  for (const candidate of candidates) {
299	    try {
300	      await db.portForward.create({
301	        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
302	      });
303	      publicPort = candidate;
304	      break;
305	    } catch (e: any) {
306	      // P2002 = another request took this port between our read and this insert.
307	      // Anything else is a real failure and must not be swallowed.
308	      if (e?.code !== "P2002") throw e;
309	    }
310	  }
311	  if (!publicPort) {
312	    return {
313	      error:
314	        "Another request took the public port we picked, several times in a row. " +
315	        "Nothing was created — please try adding the forward again.",
316	    };
317	  }
318	
319	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
320	  // A NAT Minecraft server's game port isn't forwarded until this moment (see
321	  // worker/index.ts's provision() comment) — this may be the first time its
322	  // subdomain DNS has anything valid to point at.
323	  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
324	  await db.auditLog.create({
325	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
326	  });
327	  revalidatePath(`/dashboard/servers/${serverId}`);
328	  return {};
329	}
330	
331	export async function deletePortForward(serverId: string, forwardId: string) {
332	  const { user } = await ownedServer(serverId);
333	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
334	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
335	  // If this was the game's forward, the subdomain has nothing to point at anymore.
336	  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
337	  await db.auditLog.create({
338	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
339	  });
340	  revalidatePath(`/dashboard/servers/${serverId}`);
341	}
