343	/**
344	 * Rename a paid Minecraft server's `<subdomain>.play.nxeon.cloud`. Mirrors
345	 * lib/actions-free-minecraft.ts's changeFreeMinecraftSubdomain: format/reserved
346	 * check, then let the DB's unique constraint (Server.subdomain) catch the
347	 * same-table race rather than a separate findFirst-then-update (TOCTOU).
348	 */
349	export async function changeGameSubdomain(prev: unknown, formData: FormData): Promise<{ error?: string }> {
350	  const serverId = String(formData.get("serverId") ?? "");
351	  const { user, server } = await ownedServer(serverId);
