353	  const rl = checkRateLimit(`game:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
354	  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };
355	
356	  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
357	  const formatError = validateSubdomainFormat(sub);
