13	/**
14	 * Post-deploy "Add storage": grow ONE server's own root disk by N GB without
15	 * changing its plan (CPU/RAM/plan price are untouched).
16	 *
17	 * Money path is a carbon copy of lib/actions-server.ts resizeServer:
18	 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
19	 * The wallet is only ever debited by applyDiskExpand, and only after the card
20	 * portion has cleared, so displayed === charged and nothing is charged twice.
21	 *
22	 * GROWTH IS ONE-WAY. There is deliberately no companion "shrink" action.
23	 */
24	
25	/** Max expansions a single customer may start in RATE_WINDOW_MS. */
26	const MAX_EXPANDS_PER_WINDOW = 5;
27	const RATE_WINDOW_MS = 10 * 60_000;
28	
29	async function ownedServer(serverId: string) {
30	  const user = await requireUser();
31	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
32	  if (!server) throw new Error("Not found");
33	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
34	  return { user, server };
