37	export async function expandServerDisk(
38	  serverId: string,
39	  addGB: number,
40	  useWallet: boolean = true,
41	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
42	  // Spend path: block wallet debits while an admin is impersonating.
43	  await assertNotImpersonating();
44	  const { user, server } = await ownedServer(serverId);
45	  // Purchase gate: a disk expansion is an irreversible charge.
46	  // See lib/email-verification.ts.
47	  const unverified = await emailVerificationError(user);
48	  if (unverified) return { error: unverified };
49	
50	  // Round DOWN to a purchasable amount — a malformed value can only ever cost
51	  // the customer less, never more (see normalizeExtraDiskGB).
52	  const gb = normalizeExtraDiskGB(addGB);
53	  if (gb <= 0) return { error: "Choose an amount of storage to add." };
54	
55	  // Rate limit: expansions are irreversible and each one queues real hypervisor
56	  // work, so cap how fast a single account can fire them off.
57	  const recent = await db.job.count({
58	    where: {
59	      type: "DISK_EXPAND",
60	      createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) },
61	      server: { userId: user.id },
62	    },
63	  });
64	  if (recent >= MAX_EXPANDS_PER_WINDOW) {
65	    return { error: "Too many storage expansions just now — please wait a few minutes and try again." };
66	  }
67	
68	  // Reject while another job is in flight, and only from a steady run state.
69	  // (applyDiskExpand re-checks both; this returns the friendlier message first.)
70	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
71	    return { error: "Server must be running or stopped to add storage." };
72	  }
73	  const pending = await db.job.count({
74	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
75	  });
76	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
77	
78	  // Validate + price the expansion (ownership already checked above).
79	  let quote;
80	  try {
81	    quote = await diskExpandQuote(serverId, gb);
82	  } catch (e) {
83	    if (e instanceof DiskExpandError) return { error: e.message };
84	    throw e;
85	  }
86	  const { prorateCents } = quote;
87	
88	  // Wallet-aware split — identical logic to the deploy/resize flows. AddStorage
89	  // computes the same split (lib/wallet-split.ts) so displayed === charged.
90	  const { cardCents } = walletSplit({
91	    dueCents: prorateCents,
92	    balanceCents: user.balanceCents,
93	    useWallet,
94	  });
95	
96	  // Card portion > 0 → charge ONLY the remainder on the card. The confirm route
97	  // credits the card amount to the wallet and then debits the FULL proration
98	  // (encoded as chargeCents), so the wallet absorbs its share and the card the
99	  // rest — the wallet is never touched before the card clears.
100	  if (cardCents > 0) {
101	    const checkout = await createDiskExpandCheckout(user, cardCents, {
102	      serverId,
103	      addGB: gb,
104	      hostname: server.hostname,
105	      prorateCents,
106	    });
107	    if (!checkout) {
108	      return {
109	        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
110	      };
111	    }
112	    return { checkout };
113	  }
114	
115	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
116	  // servers) → apply instantly, debiting the full proration from the wallet.
117	  try {
118	    await applyDiskExpand({ serverId, addGB: gb, actorUserId: user.id });
119	  } catch (e) {
120	    if (e instanceof DiskExpandError) return { error: e.message };
121	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
122	    throw e;
123	  }
124	  revalidatePath(`/dashboard/servers/${serverId}`);
125	  return {};
126	}
