26	// The instance states that reserve a subdomain / count as live.
27	const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
28	
29	/**
30	 * Least-loaded enabled+online Proxmox node by RAM headroom, steering away from a
31	 * node this instance would push past the CRITICAL capacity threshold when another
32	 * node has room (mirrors lib/order.ts scheduleNode). Never refuses placement for a
33	 * capacity warning — the node-capacity alert owns that signal; it only prefers a
34	 * roomier node when one exists.
35	 */
36	/**
37	 * Order a managed Nextcloud (NxCloud) instance.
38	 *
39	 * MONEY SAFETY — this mirrors the audited VPS/hosting order discipline:
40	 *   - no spending while impersonating; verified email required;
41	 *   - the wallet is charged the FULL displayed monthly price (NO first-month-free —
42	 *     that promo is shared-hosting only), in the SAME transaction that creates the
43	 *     records, so a rolled-back charge leaves no instance and no invoice;
44	 *   - the amount charged is exactly `plan.priceCents`, which is also what the
45	 *     backing Server renews at (its `serverPlan.priceCents` is seeded equal), so
46	 *     displayed === charged === renewed.
47	 *
48	 * The instance is backed by a real `Server`, created here with a PROVISION job.
49	 * The worker clones/sizes the VM and bakes in the Nextcloud install (worker/nxcloud.ts);
50	 * the instance flips to ACTIVE once it verifies serving.
51	 */
52	export async function orderNxCloud(planId: string, subdomainRaw: string, termMonthsRaw?: number): Promise<NxCloudResult> {
53	  const user = await requireUser();
54	  await assertNotImpersonating();
55	
56	  // Ordering gate. NxCloud is visible product-wide, but provisioning must not open
57	  // until the *.nxcloud.nxeon.cloud wildcard DNS exists (Caddy auto-TLS depends on
58	  // it) and the provisioning path has passed a security review. Until the owner
59	  // flips `nxcloud_ordering_enabled`, refuse before touching the wallet. This is a
60	  // pure gate — it changes no price and no money-flow logic below.
61	  if (!(await getSettingBool("nxcloud_ordering_enabled", false))) {
62	    return { error: "NxCloud isn’t open for orders yet — join the waitlist and we’ll let you know the moment it launches." };
63	  }
64	
65	  const unverified = await emailVerificationError(user);
66	  if (unverified) return { error: unverified };
67	
68	  const subdomain = normalizeSubdomain(subdomainRaw);
69	  if (!subdomain) return { error: "Choose a subdomain for your cloud." };
70	  if (!isValidSubdomainLabel(subdomain)) {
71	    return { error: "Subdomain: 3–32 lowercase letters, digits or hyphens (not a reserved word)." };
72	  }
73	
74	  const plan = await db.nxCloudPlan.findUnique({ where: { id: planId }, include: { serverPlan: true } });
75	  if (!plan || !plan.active) return { error: "That NxCloud plan isn’t available." };
76	  if (!plan.serverPlan) return { error: "This plan isn’t fully configured yet — please contact support." };
77	
78	  // The Nextcloud OS image the VM clones from (seeded by prisma/seed-nxcloud.ts).
79	  const osTemplate = await db.osTemplate.findUnique({ where: { slug: "nextcloud" } });
80	  if (!osTemplate) return { error: "NxCloud isn’t available yet — the Nextcloud image hasn’t been seeded." };
81	
82	  // Subdomain is globally unique across all customers (it's a public hostname).
83	  const taken = await db.nxCloudInstance.findFirst({
84	    where: { subdomain, status: { in: [...LIVE_STATES] } },
85	    select: { id: true, userId: true },
86	  });
87	  if (taken) {
88	    return {
89	      error:
90	        taken.userId === user.id
91	          ? "You already have a cloud with that subdomain."
92	          : "That subdomain is taken — try another.",
93	    };
94	  }
95	
96	  // Billing term (Monthly / Annual). NxCloud billing rides the backing Server, so
97	  // the term + frozen annual rate are stamped on that Server and the audited VPS
98	  // renewal sweep (worker/billing.ts) renews it at `termPriceCents(serverPlan price,
99	  // termMonths, frozen annual)`. `plan.priceCents` is seeded equal to
100	  // `serverPlan.priceCents`, so displayed === charged === renewed. The term charge
101	  // is the plan's monthly price over the term at the annual rate.
102	  const term = normalizeProductTerm(termMonthsRaw);
103	  const annualPct = await annualDiscountPct();
104	  const chargeCents = termPriceCents(plan.priceCents, term, annualPct);
105	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
106	
107	  const nodeId = (await scheduleNode(plan.serverPlan.ramMB))?.id ?? null;
108	  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
109	  const fqdn = nxcloudFqdn(subdomain, zone);
110	  const effMonthly = term > 1 ? Math.round(chargeCents / term) : 0;
111	  const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
112	
113	  let instanceId = "";
114	  try {
115	    await db.$transaction(async (tx) => {
116	      await debitWallet(tx, user.id, chargeCents);
117	      await tx.walletTransaction.create({
118	        data: {
119	          userId: user.id,
120	          amountCents: -chargeCents,
121	          description: `NxCloud: ${plan.name} (${fqdn}) — ${termLabel}`,
122	        },
123	      });
124	      await tx.invoice.create({
125	        data: invoiceCreateData({
126	          userId: user.id,
127	          description: `NxCloud: ${plan.name} (${fqdn}) — ${termLabel}`,
128	          status: "PAID",
129	          period: { start: new Date(), end: addMonths(new Date(), term) },
130	          lineItems: [
131	            { description: `${plan.name} — managed Nextcloud (${fqdn}) — ${termLabel}`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
132	          ],
133	        }),
134	      });
135	      // The backing VM. A normal Server — it renews / duns / suspends / monitors
136	      // through the exact same audited machinery as a VPS. VM snapshot backups are
137	      // ON by default (data-loss safety, spec §6); a public IP is requested so the
138	      // instance is reachable by hostname for auto-TLS.
139	      const server = await tx.server.create({
140	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
141	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
142	        data: {
143	          name: subdomain,
144	          hostname: subdomain,
145	          userId: user.id,
146	          planId: plan.serverPlanId,
147	          osTemplateId: osTemplate.id,
148	          nodeId,
149	          autoBackup: true,
150	          backupIntervalHours: 24,
151	          // The customer's chosen term (Monthly / Annual). The VPS renewal sweep reads
152	          // this + annualDiscountPct off the Server and renews at the sold rate.
153	          termMonths: term,
154	          // Sold at full price — 0% off — so no later proration can claw a discount
155	          // that was never given (see Server.termPromoPercent).
156	          termPromoPercent: 0,
157	          // The annual rate frozen at sale, so the renewal bills the SAME price the
158	          // order charged even if the admin retunes the discount afterwards.
159	          annualDiscountPct: annualPct,
160	          wantsDedicatedIp: true,
161	          isFree: false,
162	          expiresAt: addMonths(new Date(), term),
163	        } as Prisma.ServerUncheckedCreateInput,
164	      });
165	      const inst = await tx.nxCloudInstance.create({
166	        data: {
167	          userId: user.id,
168	          planId: plan.id,
169	          serverId: server.id,
170	          subdomain,
171	          status: "PENDING",
172	          adminUser: "admin",
173	          storageQuotaMB: plan.storageGB * 1024,
174	        },
175	      });
176	      instanceId = inst.id;
177	      await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
178	    });
179	  } catch (e) {
180	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
181	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
182	  }
183	
184	  await db.auditLog
185	    .create({ data: { userId: user.id, action: "nxcloud.order", detail: `${plan.name} · ${fqdn}` } })
186	    .catch(() => {});
187	  revalidatePath("/dashboard/nxcloud");
188	  return { ok: true, instanceId };
189	}
