227	    storageQuotaMB: a.storageQuotaMB,
228	    storageUsedMB: a.storageUsedMB ?? null,
229	    usageAt: a.usageAt?.toISOString() ?? null,
230	    sslActive: a.sslActive,
231	    version: a.version,
232	    error: a.error,
233	    expiresAt: a.server?.expiresAt?.toISOString() ?? null,
234	    createdAt: a.createdAt.toISOString(),
235	  };
