269	/**
270	 * Retry a FAILED NxCloud instance whose backing VM never came up. Re-enqueues a
271	 * PROVISION job on the same Server (the provision handler keeps any persisted
272	 * vmid, so a retry resumes rather than leaking a second VM) and moves both the
273	 * instance and its server back into the transitional PROVISIONING state so the
274	 * dashboard shows "setting up" instead of the failed card. Owner/admin only,
275	 * guarded to FAILED. Mirrors retryHostingProvision / retryProvision.
276	 */
277	export async function retryNxcloud(instanceId: string): Promise<NxCloudResult> {
278	  const user = await requireUser();
279	  const inst = await db.nxCloudInstance.findUnique({
280	    where: { id: instanceId },
281	    select: { userId: true, status: true, serverId: true },
282	  });
283	  if (!inst) return { error: "Not found." };
284	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
285	  if (inst.status !== "FAILED") return { error: "This cloud isn’t in a failed state." };
286	  if (!inst.serverId) return { error: "No backing server to retry — please contact support." };
287	  // Don't double-enqueue if a job is already in flight on the backing server.
288	  const inflight = await db.job.count({
289	    where: { serverId: inst.serverId, status: { in: ["QUEUED", "RUNNING"] } },
290	  });
291	  if (inflight > 0) return { error: "A setup task is already running on this cloud." };
292	
293	  await db.$transaction([
294	    db.nxCloudInstance.update({ where: { id: instanceId }, data: { status: "PENDING", error: null } }),
295	    db.server.update({ where: { id: inst.serverId }, data: { status: "PROVISIONING", provisionError: null } }),
296	    db.job.create({ data: { type: "PROVISION", serverId: inst.serverId } }),
297	  ]);
298	  await db.auditLog
299	    .create({ data: { userId: user.id, action: "nxcloud.retry_provision", detail: instanceId } })
300	    .catch(() => {});
301	  revalidatePath("/dashboard/nxcloud");
302	  return { ok: true };
303	}
