318	/**
319	 * Terminate an instance: destroy the backing VM (enqueue a Server DELETE — the
320	 * audited teardown that stops billing and purges the disk) and remove the
321	 * instance record. Irreversible; the customer's files go with the VM.
322	 */
323	export async function terminateNxcloud(instanceId: string): Promise<NxCloudResult> {
324	  const user = await requireUser();
325	  await assertNotImpersonating();
326	  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, serverId: true } });
327	  if (!inst) return { error: "Not found." };
328	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
329	  if (inst.serverId) {
330	    await db.job.create({ data: { type: "DELETE", serverId: inst.serverId } });
331	  }
332	  // Drop the wrapper row (tasks cascade). The DELETE job tears the VM down.
333	  await db.nxCloudInstance.delete({ where: { id: instanceId } });
334	  await db.auditLog.create({ data: { userId: user.id, action: "nxcloud.terminate", detail: instanceId } }).catch(() => {});
335	  revalidatePath("/dashboard/nxcloud");
336	  return { ok: true };
337	}
