761	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
762	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
763	  // can render it — a `throw` here reaches the browser as Next's redacted generic
764	  // error, discarding the specific, actionable message (e.g. "Delete your data
765	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
766	  const { user, server } = await ownedServer(serverId);
767	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
768	    start: "START",
769	    stop: "STOP",
770	    reboot: "REBOOT",
771	    reinstall: "REINSTALL",
772	    delete: "DELETE",
773	  };
774	  const type = allowed[action];
775	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
776	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
777	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
778	  }
779	
780	  // A reinstall wipes the whole VM, including any block-storage volume the VM
781	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
782	  //
783	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
784	  // deliberately keeps `serverId` set so the volume can be re-attached
785	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
786	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
787	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
788	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
789	  // Reinstall — both guards see zero attached volumes, and the purge takes the
790	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
791	  // by serverId; this path did not. That asymmetry was the bug.
792	  if (type === "REINSTALL") {
793	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
794	    if (pinnedVolumes > 0) {
795	      return {
796	        error:
797	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
798	      };
799	    }
800	  }
801	
802	  const pending = await db.job.count({
803	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
804	  });
805	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
806	  // with no explanation. Tell them why.
807	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
808	
809	  if (type === "DELETE") {
810	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
811	  }
812	  await db.job.create({ data: { type, serverId } });
813	  await audit(user.id, `server.${action}`, serverId);
814	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
815	  revalidatePath(`/dashboard/servers/${serverId}`);
816	}
