1275	/**
1276	 * Reconcile a server's DB status from its REAL Proxmox VM state.
1277	 *
1278	 * A VPS can be stranded in ERROR even though its VM is fully built and running
1279	 * (a worker restart mid-provision + a retry that treated "already running" as
1280	 * fatal). The VM, IP, forward and cloud-init are all fine — only the DB status
1281	 * is wrong. This is the one-click admin recovery: read the truth from the
1282	 * hypervisor and make the row match it.
1283	 *
1284	 * The web process is UNPRIVILEGED and must never touch iptables, so instead of
1285	 * re-syncing port-forwards itself it ENQUEUES a `SYNC_FORWARDS` job for the root
1286	 * worker. Fleet/admin RBAC via `requireArea("fleet")`, matching the admin
1287	 * servers pages.
1288	 */
1289	export async function reconcileServerFromProxmox(
1290	  serverId: string
1291	): Promise<{ ok?: true; status?: string; message?: string; error?: string }> {
1292	  const admin = await requireArea("fleet");
1293	
1294	  const server = await db.server.findUnique({
1295	    where: { id: serverId },
1296	    include: {
1297	      node: true,
1298	      user: { select: { id: true, email: true } },
1299	      plan: { select: { name: true } },
1300	    },
1301	  });
1302	  if (!server) return { error: "Server not found." };
1303	  if (!server.vmid || !server.node) {
1304	    return { error: "This server has no VM on Proxmox yet — use Retry/Delete, not reconcile." };
1305	  }
1306	
1307	  const node = server.node;
1308	  const client = pveFor({
1309	    apiUrl: node.apiUrl,
1310	    pveNode: node.pveNode,
1311	    tokenId: node.tokenId,
1312	    tokenSecret: node.tokenSecret,
1313	  });
1314	
1315	  let vmState: string | undefined;
1316	  try {
1317	    const s = await client.vmStatus(server.vmid);
1318	    vmState = typeof s?.status === "string" ? s.status : undefined;
1319	  } catch {
1320	    return { error: "Couldn't reach the hypervisor — try again." };
1321	  }
1322	
1323	  const prev = server.status;
1324	
1325	  if (vmState === "running") {
1326	    await db.server.update({
1327	      where: { id: server.id },
1328	      data: { status: "RUNNING", provisionError: null },
1329	    });
1330	    // Unprivileged web process → hand the iptables work to the root worker.
1331	    await db.job.create({ data: { type: "SYNC_FORWARDS", serverId: server.id } });
1332	
1333	    // A stranded customer may never have received their deployment email. If this
1334	    // is a transition INTO running from a broken/incomplete state, (re)send it —
1335	    // the EmailLog dedupe guarantees no double-send if they already got it.
1336	    if (prev === "ERROR" || prev === "PENDING" || prev === "PROVISIONING") {
1337	      await sendServerDeployedEmail(server, server.user);
1338	    }
1339	
1340	    await audit(admin.id, "server.reconcile", `${server.hostname} ${server.vmid} → RUNNING`);
1341	    revalidatePath("/admin/servers");
1342	    revalidatePath(`/admin/servers/${server.id}`);
1343	    return { ok: true, status: "RUNNING" };
1344	  }
1345	
1346	  if (vmState === "stopped") {
1347	    await db.server.update({
1348	      where: { id: server.id },
1349	      data: { status: "STOPPED", provisionError: null },
1350	    });
1351	    await audit(admin.id, "server.reconcile", `${server.hostname} ${server.vmid} → STOPPED`);
1352	    revalidatePath("/admin/servers");
1353	    revalidatePath(`/admin/servers/${server.id}`);
1354	    return { ok: true, status: "STOPPED" };
1355	  }
1356	
1357	  // Any other/unknown state (paused, prelaunch, migrating…): don't guess. Leave
1358	  // the status as-is and report what the VM actually said.
1359	  await audit(admin.id, "server.reconcile", `${server.hostname} ${server.vmid} → no-op (${vmState ?? "unknown"})`);
1360	  return {
1361	    message: `The VM reports "${vmState ?? "unknown"}"; status left unchanged. Try again once it settles.`,
1362	  };
1363	}
