517	  const user = await requireUser();
518	  // Spend path: never move a customer's money while an admin is impersonating them.
519	  // Caught (not left to throw uncaught) so an impersonating admin sees this exact
520	  // message inline — the bare throw used to crash the whole page with a generic
521	  // "Something went wrong" screen instead, a real bug hit every time an admin
522	  // testing the wizard while impersonating tried to pay.
523	  try {
524	    await assertNotImpersonating();
525	  } catch (e) {
526	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
527	  }
528	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
529	  // one where an unreachable address is most expensive: without it we would take
530	  // a real payment for a machine whose credentials have nowhere to go.
531	  const unverified = await emailVerificationError(user);
532	  if (unverified) return { error: unverified };
533	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
534	  const limitErr = await serverLimitError(user.id);
535	  if (limitErr) return { error: limitErr };
536	  const intent = intentFromFormData(formData);
537	  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
538	  // /dashboard/deploy, captured into a cookie by PartnerSourceCapture). Undefined
539	  // for a direct order, so it drops out of the Stripe-metadata JSON round-trip
540	  // like extraDiskGB/backupTier above.
541	  intent.partnerSource = partnerSourceFromCookie(await cookies());
542	
543	  let quote;
544	  try {
545	    quote = await orderQuote(intent);
546	  } catch (e) {
547	    if (e instanceof OrderError) return { error: e.message };
548	    throw e;
549	  }
